const mobileIcon={menu:'<path d="M3 6h18M3 12h18M3 18h18"/>',search:'<circle cx="10" cy="10" r="6.5"/><path d="m15 15 6 6"/>',user:'<circle cx="12" cy="7" r="4"/><path d="M3 22c0-11 18-11 18 0"/>',cart:'<path d="M2 3h3l3 12h11l3-9H6"/><circle cx="9" cy="20" r="1"/><circle cx="19" cy="20" r="1"/>'};
const svg=n=>'<svg viewBox="0 0 24 24" aria-hidden="true">'+mobileIcon[n]+'</svg>';
const header=document.createElement('div');header.className='mobile-header';
const logo=document.querySelector('.headerMainContainer .logo img');
header.innerHTML='<div class="mobile-header-top"><button type="button" id="mobile-open" aria-label="Abrir menu" aria-expanded="false" aria-controls="mobile-menu">'+svg('menu')+'</button><a href="/" class="mobile-logo" aria-label="Página inicial"><img alt="Growth Supplements" src="'+logo.getAttribute('src')+'"></a><div class="mobile-header-actions"><button type="button" id="mobile-account" aria-label="Minha conta">'+svg('user')+'</button><button type="button" id="mobile-cart" class="mobile-cart" aria-label="Abrir carrinho">'+svg('cart')+'<span>0</span></button></div></div><form class="mobile-search" role="search"><input type="search" aria-label="Buscar produto" placeholder="Encontre o suplemento ideal para você"><button type="submit" aria-label="Buscar">'+svg('search')+'</button></form>';
document.querySelector('.headerMainContainer').before(header);
const menu=document.createElement('aside');menu.id='mobile-menu';menu.className='mobile-menu';menu.inert=true;menu.setAttribute('aria-label','Menu de categorias');
menu.innerHTML='<div class="mobile-menu-head"><strong>MENU</strong><button type="button" aria-label="Fechar menu">×</button></div><div class="mobile-menu-intro">Olá! Bem-vindo à Growth.</div>';
const categories=[['Categorias',[['Kits','/kits/'],['Proteínas','/proteina/'],['Veganos','/vegano/'],['Vegetarianos','/vegetariano/'],['Termogênicos','/termogenico/'],['Vitaminas','/vitaminas/'],['Aminoácidos','/aminoacidos/'],['Carboidratos','/carboidratos/'],['Acessórios','/acessorios/']]],['Objetivos',[['Massa muscular','/massa-muscular/'],['Emagrecimento','/emagrecimento/'],['Energia','/energia/'],['Saúde e qualidade de vida','/saude-e-qualidade-de-vida/']]]];
for(const [name,links] of categories){const d=document.createElement('details');const s=document.createElement('summary');s.textContent=name;d.append(s);for(const [label,url]of links){const a=document.createElement('a');a.href=url;a.textContent=label;d.append(a)}menu.append(d)}
for(const label of ['Top 20','Lançamentos','Whey Protein','Creatina','Vitaminas','Pré-treino','Snacks','Roupas','Acessórios','Kits','Ofertas']){const a=document.createElement('a');a.href='#';a.textContent=label;menu.append(a)}
document.body.append(menu);const overlay=document.createElement('div');overlay.className='mobile-overlay';document.body.append(overlay);
const open=document.getElementById('mobile-open');function closeMenu(){menu.classList.remove('open');overlay.classList.remove('open');document.body.classList.remove('menu-is-open');menu.inert=true;open.setAttribute('aria-expanded','false');open.focus()}
open.addEventListener('click',()=>{menu.inert=false;menu.classList.add('open');overlay.classList.add('open');document.body.classList.add('menu-is-open');open.setAttribute('aria-expanded','true');menu.querySelector('button').focus()});menu.querySelector('button').addEventListener('click',closeMenu);overlay.addEventListener('click',closeMenu);document.addEventListener('keydown',e=>{if(e.key==='Escape'&&menu.classList.contains('open'))closeMenu();if(e.key==='Tab'&&menu.classList.contains('open')){const focusable=[...menu.querySelectorAll('button,summary,a')].filter(e=>e.checkVisibility());const first=focusable[0],last=focusable.at(-1);if(e.shiftKey&&document.activeElement===first){e.preventDefault();last.focus()}else if(!e.shiftKey&&document.activeElement===last){e.preventDefault();first.focus()}}});menu.addEventListener('click',e=>{if(e.target.closest('a'))closeMenu()});
document.getElementById('mobile-account').onclick=()=>show('Minha conta','O acesso à conta será conectado na próxima etapa da loja.');document.getElementById('mobile-cart').onclick=()=>show('Seu carrinho está vazio','Os produtos e suas variações serão conectados na próxima etapa.');
document.querySelectorAll('.menuRodape-container-nv1').forEach(item=>{const title=item.querySelector('.item__title');if(!title)return;title.setAttribute('tabindex','0');title.setAttribute('role','button');title.setAttribute('aria-expanded','false');function toggle(e){if(innerWidth>=992)return;e.preventDefault();e.stopPropagation();const expanded=item.classList.toggle('mobile-expanded');title.setAttribute('aria-expanded',String(expanded))}title.addEventListener('click',toggle);title.addEventListener('keydown',e=>{if(e.key==='Enter'||e.key===' ')toggle(e)})});
document.querySelectorAll('.btFavorito').forEach(button=>{button.addEventListener('click',()=>{const enabled=button.getAttribute('aria-pressed')!=='true';button.setAttribute('aria-pressed',String(enabled));button.style.color=enabled?'#e44363':'';button.querySelectorAll('svg path').forEach(p=>p.style.fill=enabled?'#e44363':'none')})});
